// HAND-WRITTEN TEST — NOT generated by openapi-generator (zz_ prefix +
// _test.go suffix keep it clear of regeneration and non-test builds).
//
// This canonical Attributes v2 contract package is decoded by Core (callback
// requests carry []RequestAttribute; responses carry []BaseAttributeContentDtoV3)
// and by connectors (the definition registry is []BaseAttributeDto). These
// tests lock in the discriminator-aware oneOf decoders that tools/fixoneof
// patches in, so a future regeneration that forgets to re-run fixoneof — or a
// fixoneof change that breaks a variant — fails loudly here.
package v2

import (
	"encoding/json"
	"reflect"
	"strings"
	"testing"
)

const fullProps = `{"label":"L","visible":true,"required":true,"readOnly":false,"list":false,"multiSelect":false,"extensibleList":false}`

// infoMetaProps satisfies InfoAttributeProperties / MetadataAttributeProperties
// (only label+visible required).
const infoMetaProps = `{"label":"L","visible":true}`

type oneOfWrapper interface {
	json.Unmarshaler
	json.Marshaler
	GetActualInstance() any
}

type oneOfCase struct {
	name       string
	payload    string
	newWrapper func() oneOfWrapper
	wantType   any      // pointer to the expected concrete variant
	discSubstr []string // must survive a marshal round-trip
}

func runCases(t *testing.T, wrapper string, cases []oneOfCase) {
	t.Helper()
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			wantT := reflect.TypeOf(tc.wantType)

			w := tc.newWrapper()
			if err := json.Unmarshal([]byte(tc.payload), w); err != nil {
				t.Fatalf("%s: unmarshal %s: %v", wrapper, tc.payload, err)
			}
			got := w.GetActualInstance()
			if got == nil {
				t.Fatalf("%s: GetActualInstance nil after decoding %s", wrapper, tc.name)
			}
			if reflect.TypeOf(got) != wantT {
				t.Fatalf("%s: variant = %v, want %v", wrapper, reflect.TypeOf(got), wantT)
			}

			b, err := json.Marshal(w)
			if err != nil {
				t.Fatalf("%s: marshal: %v", wrapper, err)
			}
			for _, sub := range tc.discSubstr {
				if !strings.Contains(string(b), sub) {
					t.Fatalf("%s: marshalled JSON missing %q\ngot: %s", wrapper, sub, b)
				}
			}

			w2 := tc.newWrapper()
			if err := json.Unmarshal(b, w2); err != nil {
				t.Fatalf("%s: round-trip unmarshal: %v\nbytes: %s", wrapper, err, b)
			}
			if reflect.TypeOf(w2.GetActualInstance()) != wantT {
				t.Fatalf("%s: round-trip variant = %v, want %v", wrapper, reflect.TypeOf(w2.GetActualInstance()), wantT)
			}
		})
	}
}

func assertUnknown(t *testing.T, wrapper string, w json.Unmarshaler, payload string) {
	t.Helper()
	err := json.Unmarshal([]byte(payload), w)
	if err == nil {
		t.Fatalf("%s: expected error for unknown discriminator, got nil", wrapper)
	}
	if !strings.Contains(err.Error(), "unknown") {
		t.Fatalf("%s: error %q does not mention \"unknown\"", wrapper, err.Error())
	}
}

// RequestAttribute — discriminator "version" (v2/v3). On the callback wire as
// currentAttributes / scope attributes.
func TestOneOfRequestAttribute(t *testing.T) {
	runCases(t, "RequestAttribute", []oneOfCase{
		{
			name:       "v3",
			payload:    `{"version":"v3","uuid":"u","name":"n","contentType":"string"}`,
			newWrapper: func() oneOfWrapper { return &RequestAttribute{} },
			wantType:   &RequestAttributeV3{},
			discSubstr: []string{`"version":"v3"`},
		},
		{
			name:       "v2",
			payload:    `{"version":"v2","uuid":"u","name":"n","contentType":"string"}`,
			newWrapper: func() oneOfWrapper { return &RequestAttribute{} },
			wantType:   &RequestAttributeV2{},
			discSubstr: []string{`"version":"v2"`},
		},
	})
	assertUnknown(t, "RequestAttribute", &RequestAttribute{}, `{"version":"v9"}`)
}

